-- Source: Cin7 OrdersExport (future: Fulfil). We MIRROR the ERP for po/sku/qty/cost; rows with no
-- SKU or QTY (landed costs etc) are excluded. carton_qty is product-master data (sku_labels), so it
-- is sourced via the view, not stored. partial_carton_approved is OUR overlay flag (preserve on
-- future re-syncs — an n8n upsert should keep it; this one-time load resets it to false).
