-- carton_qty sourced from product master (sku_labels); full_carton_check recomputed
create view planner.v_purchase_order_lines as
select l.id, l.po_sku, l.po, l.sku, l.qty, sl.carton_qty, l.partial_carton_approved, l.cost_price, l.po_status,
  case when sl.carton_qty is null or sl.carton_qty=0 then null
       when l.qty % sl.carton_qty = 0 then '✅ Full Cartons'
       when l.partial_carton_approved then 'OK Partial'
       else '⚠️ Partial Carton - up to '||(ceil(l.qty::numeric/sl.carton_qty)*sl.carton_qty)::int
  end full_carton_check
from planner.purchase_order_lines l
left join planner.sku_labels sl on sl.sku=l.sku;
